// Guía de qué servicio de cómputo cubre cada necesidad. Corrige su defecto principal.
export const guia = {
  filas: [
    { necesidad: "Servidor virtual con el sistema operativo y el software que elige el equipo", servicio: "Amazon EC2" },
    { necesidad: "Código que responde a un evento de un bucket sin gestionar servidores", servicio: "Amazon EC2" },
    { necesidad: "Orquestación de contenedores totalmente administrada de AWS", servicio: "Amazon ECS" },
    { necesidad: "Aplicaciones de Kubernetes que se despliegan sin refactorizarlas", servicio: "Amazon EKS" },
    { necesidad: "Contenedores sin gestionar servidores ni clústeres de instancias EC2", servicio: "AWS Fargate" },
  ],
};

solution.code:
export const guia = {
  filas: [
    { necesidad: "Servidor virtual con el sistema operativo y el software que elige el equipo", servicio: "Amazon EC2" },
    { necesidad: "Código que responde a un evento de un bucket sin gestionar servidores", servicio: "AWS Lambda" },
    { necesidad: "Orquestación de contenedores totalmente administrada de AWS", servicio: "Amazon ECS" },
    { necesidad: "Aplicaciones de Kubernetes que se despliegan sin refactorizarlas", servicio: "Amazon EKS" },
    { necesidad: "Contenedores sin gestionar servidores ni clústeres de instancias EC2", servicio: "AWS Fargate" },
  ],
};

spec.code:
const fila = guia.filas.find((f) => f.necesidad.startsWith("Código que responde"));
assert.ok(fila, "debe existir la fila del código que responde a un evento");
assert.strictEqual(fila.servicio, "AWS Lambda");

const validos = ["Amazon EC2", "AWS Lambda", "Amazon ECS", "Amazon EKS", "AWS Fargate"];
for (const fila of guia.filas) {
  assert.ok(validos.includes(fila.servicio), fila.necesidad + " tiene un servicio no válido");
}

const esperado = {
  "Servidor virtual con el sistema operativo y el software que elige el equipo": "Amazon EC2",
  "Orquestación de contenedores totalmente administrada de AWS": "Amazon ECS",
  "Aplicaciones de Kubernetes que se despliegan sin refactorizarlas": "Amazon EKS",
  "Contenedores sin gestionar servidores ni clústeres de instancias EC2": "AWS Fargate",
};
for (const [necesidad, servicio] of Object.entries(esperado)) {
  const fila = guia.filas.find((f) => f.necesidad === necesidad);
  assert.ok(fila, necesidad + " debe seguir existiendo");
  assert.strictEqual(fila.servicio, servicio);
}

exercises.starterCode:
// Calcula cuántas instancias hacen falta para atender una carga. Corrige su defecto principal.
export function instanciasNecesarias(carga: number, capacidadPorInstancia: number, minimo: number): number {
  return Math.max(minimo, Math.floor(carga / capacidadPorInstancia));
}

solution.code:
export function instanciasNecesarias(carga: number, capacidadPorInstancia: number, minimo: number): number {
  return Math.max(minimo, Math.ceil(carga / capacidadPorInstancia));
}

spec.code:
for (const carga of [999, 1000, 1001, 4321]) {
  const n = instanciasNecesarias(carga, 100, 1);
  assert.ok(n * 100 >= carga, "las instancias deben cubrir la carga " + carga);
}
